import type { BuiltLevel, BuiltWorld } from "@hexhue/core";
import moonlit from "./generated/moonlit.json";

/** Shipped worlds, in play order. Generated by `npm run levels`; validated in CI. */
export const worlds: readonly BuiltWorld[] = [moonlit as unknown as BuiltWorld];

export function levelAt(worldIndex: number, levelIndex: number): BuiltLevel | null {
  return worlds[worldIndex]?.levels[levelIndex] ?? null;
}
